INSERT INTO `venue`.`venues` (`venue_id`, `name`, `location`, `facilities`, `accessibility`, `layouts`, `operating_hours`, `turnaround_minutes`, `is_active`, `created_at`, `code`, `address`, `floor`, `description`, `setup_minutes`, `emergency_access`, `restrictions`) VALUES
  ('v1', 'Marina Hall A', 'HarbourFront Centre', '[\"Projector\", \"PA system\", \"Video-conferencing\", \"Stage\"]', '[\"Wheelchair accessible\", \"Accessible restrooms nearby\"]', '[{\"name\": \"Theatre\", \"capacity\": 300}, {\"name\": \"Classroom\", \"capacity\": 180}, {\"name\": \"Banquet\", \"capacity\": 220}]', '[{\"day\": \"Mon\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Tue\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Wed\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Thu\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Fri\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Sat\", \"opens\": \"08:00\", \"closes\": \"22:00\"}, {\"day\": \"Sun\", \"opens\": \"08:00\", \"closes\": \"22:00\"}]', 60, 1, @now + INTERVAL 0 SECOND, 'MH-A', '1 HarbourFront Walk, Singapore 098585', '2', 'ConnectSphere\'s largest multipurpose hall.', 30, 'Four exits: two to the waterfront promenade, two to the lift lobby. Assembly point at the promenade. Fire engine access from HarbourFront Walk.', 'No open flames or haze machines. Amplified sound must end by 22:00. Floor load 5 kN/m2.'),
  ('v2', 'Riverside Room 204', 'HarbourFront Centre', '[\"Projector\", \"Whiteboard\"]', '[\"Wheelchair accessible\"]', '[{\"name\": \"Boardroom\", \"capacity\": 20}, {\"name\": \"Classroom\", \"capacity\": 80}]', '[{\"day\": \"Mon\", \"opens\": \"08:00\", \"closes\": \"20:00\"}, {\"day\": \"Tue\", \"opens\": \"08:00\", \"closes\": \"20:00\"}, {\"day\": \"Wed\", \"opens\": \"08:00\", \"closes\": \"20:00\"}, {\"day\": \"Thu\", \"opens\": \"08:00\", \"closes\": \"20:00\"}, {\"day\": \"Fri\", \"opens\": \"08:00\", \"closes\": \"20:00\"}, {\"day\": \"Sat\", \"opens\": \"08:00\", \"closes\": \"20:00\"}]', 30, 1, @now + INTERVAL 0 SECOND, 'RS-204', '1 HarbourFront Walk, Singapore 098585', '2', 'Mid-sized meeting room.', 15, 'Two exits to the level 2 corridor; nearest stairwell 15 m to the left. Assembly point at the taxi stand.', 'Room only. No catering inside; no rigging from the ceiling.'),
  ('v3', 'Exhibition Hall B', 'Suntec Singapore Convention & Exhibition Centre', '[\"Loading dock\", \"PA system\", \"Booth power points\"]', '[\"Wheelchair accessible\", \"Accessible restrooms nearby\"]', '[{\"name\": \"Exhibition\", \"capacity\": 500}, {\"name\": \"Theatre\", \"capacity\": 350}]', '[{\"day\": \"Mon\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Tue\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Wed\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Thu\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Fri\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Sat\", \"opens\": \"07:00\", \"closes\": \"23:00\"}, {\"day\": \"Sun\", \"opens\": \"07:00\", \"closes\": \"23:00\"}]', 120, 1, @now + INTERVAL 0 SECOND, 'EH-B', '1 Raffles Boulevard, Singapore 039593', '1', 'Large exhibition space with loading dock access.', 45, 'Eight exits around the hall, two wide enough for vehicles. Assembly point at the north plaza. Emergency vehicles via Temasek Boulevard loading bay.', 'Exhibition stands must keep 3 m aisles to every exit. Generators need the venue\'s approval.'),
  ('v4', 'Skyline Boardroom', 'One Raffles Place', '[\"Video-conferencing\", \"Smart TV\"]', '[\"Wheelchair accessible\"]', '[{\"name\": \"Boardroom\", \"capacity\": 20}]', '[{\"day\": \"Mon\", \"opens\": \"08:00\", \"closes\": \"18:00\"}, {\"day\": \"Tue\", \"opens\": \"08:00\", \"closes\": \"18:00\"}, {\"day\": \"Wed\", \"opens\": \"08:00\", \"closes\": \"18:00\"}, {\"day\": \"Thu\", \"opens\": \"08:00\", \"closes\": \"18:00\"}, {\"day\": \"Fri\", \"opens\": \"08:00\", \"closes\": \"18:00\"}]', 15, 1, @now + INTERVAL 0 SECOND, 'SB-18', '1 Raffles Place, Singapore 048616', '18', 'Executive boardroom with skyline views.', 10, 'One exit to the lift lobby; fire stairs beside the lifts. Assembly point at Raffles Place park.', 'Maximum 20 people. No food or drinks other than water.');
